namespace Metis.Intake.Features.SubmitApplication;

/// <summary>POST /api/applications body. <see cref="Id"/> is generated by the caller so a retry is safe.</summary>
internal sealed record SubmitApplicationRequest(
    Guid Id,
    string? DealName,
    string? Sponsor,
    string? AssetType,
    string? Region,
    decimal LoanAmount,
    decimal PropertyValue,
    string? Currency,
    decimal DebtServiceCover,
    int SponsorCompletedDeals);
